{
  "name": "Gilson GSIOC 兼容液体处理仪器",
  "name_en": "Gilson GSIOC-compatible liquid handling instrument",
  "manufacturer": "Gilson",
  "description": "采用 GSIOC 串口通信协议的 Gilson 实验室仪器，常见于液体处理、进样、输液或收集类设备。此类仪器通常用于分析化学与自动化实验流程中的样品传输、进样控制和流路操作。",
  "description_en": "A Gilson laboratory instrument that uses the GSIOC serial communication protocol, commonly found in devices for liquid handling, sample introduction, pumping, or collection. Such instruments are typically used in analytical chemistry and laboratory automation workflows for sample transfer, injection control, and fluid-path operations.",
  "tag_hints": [
    "Gilson",
    "GSIOC serial communication",
    "liquid handling",
    "lab automation",
    "sample injection",
    "pump control",
    "fraction collection"
  ],
  "actions": [
    {
      "action_name": "auto-createSerial",
      "description": "创建与仪器的串口通信连接。",
      "description_en": "Create a serial communication connection to the instrument."
    },
    {
      "action_name": "auto-closeSerial",
      "description": "关闭与仪器的串口连接。",
      "description_en": "Close the serial connection to the instrument."
    },
    {
      "action_name": "auto-connect",
      "description": "按 GSIOC 设备 ID 连接目标仪器。",
      "description_en": "Connect to the target instrument by GSIOC device ID."
    },
    {
      "action_name": "auto-iCommand",
      "description": "向仪器发送即时命令并读取返回。",
      "description_en": "Send an immediate command to the instrument and read the response."
    },
    {
      "action_name": "auto-bCommand",
      "description": "向仪器发送缓冲命令序列。",
      "description_en": "Send a buffered command sequence to the instrument."
    }
  ]
}

